// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address target = address(new Eater());
        vm.deal(address(0xbeef), 1 ether);
        vm.prank(address(0xbeef));
        (bool ok,) = address(c).call{value: 1 ether}("");
        assertTrue(ok);
        c.sendMoney(target, 0.5 ether);
        assertEq(target.balance, 0.5 ether);
    }
}

contract Eater {
    receive() external payable {}
}
